  if (Array.isArray(value)) {
    return value.every((r) => r && typeof r === "object" && !Array.isArray(r)) ? value : [];
  }
  if (!value || typeof value !== "object") return [];
  const v = value;
  const rows = v.rows ?? v.data ?? v.results;
